// The shipping on-device generator (Shared/MYBRulesGen.h + rules/generate.js in JavaScriptCore) must produce exactly the bundled PACs.
#import "../Shared/MYBRulesGen.h"
static int failures=0;
#define CHECK(c,m) do{if(!(c)){fprintf(stderr,"FAIL: %s (line %d)\n",m,__LINE__);failures++;}}while(0)
int main(int argc,char **argv){@autoreleasepool{
 if(argc<3){fprintf(stderr,"usage: rules-gen-native <generator dir> <pacs dir>\n");return 2;}
 NSString *gen=@(argv[1]),*pacs=@(argv[2]);
 NSData *canon=[NSData dataWithContentsOfFile:[gen stringByAppendingPathComponent:@"canonical.json"]];
 NSString *why=nil;NSDictionary *out=MYBGenerateModePACs(canon,gen,&why);
 if(!out)fprintf(stderr,"generator said: %s\n",why.UTF8String?:"(no reason)");CHECK(out&&!why,"the bundled canonical rules generate");
 CHECK(out.count==40&&out.count==MYBGeneratedPACNames().count,"32 combinations and 8 historical names");
 for(NSString *name in MYBGeneratedPACNames()){NSData *bundled=[NSData dataWithContentsOfFile:[pacs stringByAppendingPathComponent:[name stringByAppendingString:@".pac"]]];CHECK([out[name] isEqualToData:bundled],"generated bytes equal the bundled PAC");}
 CHECK(MYBGenerationStamp(out)>0,"the generation has a stamp");
 NSMutableDictionary *bad=[NSJSONSerialization JSONObjectWithData:canon options:NSJSONReadingMutableContainers error:NULL];[bad[@"base"][@"domains"] addObject:@"apple.com"];
 why=nil;CHECK(MYBGenerateModePACs([NSJSONSerialization dataWithJSONObject:bad options:0 error:NULL],gen,&why)==nil&&[why containsString:@"protected service"],"a rule set that blocks Apple in Default is rejected");
 bad=[NSJSONSerialization JSONObjectWithData:canon options:NSJSONReadingMutableContainers error:NULL];bad[@"transport"][@"bypass"]=@"DIRECT";
 why=nil;CHECK(MYBGenerateModePACs([NSJSONSerialization dataWithJSONObject:bad options:0 error:NULL],gen,&why)==nil,"a changed bypass route is rejected");
 why=nil;CHECK(MYBGenerateModePACs([@"not json" dataUsingEncoding:NSUTF8StringEncoding],gen,&why)==nil&&why.length,"garbage is rejected");
 why=nil;CHECK(MYBGenerateModePACs(canon,@"/nonexistent",&why)==nil&&[why containsString:@"generator"],"a missing generator is reported");
 CHECK(MYBPACSelfCheck([@"function FindProxyForURL(u,h){return 'PROXY 127.0.0.1:8021';}" dataUsingEncoding:NSUTF8StringEncoding],@"Default")!=nil,"a PAC that blocks everything fails the self check");
 CHECK(MYBPACSelfCheck([@"function FindProxyForURL(u,h){return 'DIRECT';}" dataUsingEncoding:NSUTF8StringEncoding],@"Default")!=nil,"a PAC that blocks nothing fails the self check");
 CHECK(MYBPACSelfCheck([@"syntax error (" dataUsingEncoding:NSUTF8StringEncoding],@"Default")!=nil,"a PAC that does not evaluate fails the self check");
 if(failures){fprintf(stderr,"%d generator check(s) FAILED\n",failures);return 1;}
 printf("On-device generator checks passed: byte-identical to the bundled PACs, bad rules refused.\n");
}return 0;}
